const EventEmitter = require("events");
const functions = require("./jsondb.js");

/**
 * Shared helpers for async key-value adapters such as MySQL and Firebase.
 * @module functions/adapterStore
 */

/**
 * @typedef {Object} KeyValueAdapterOptions
 * @property {string} [seperator="."] Nested-key separator.
 */

function clone(value) {
  if (value === undefined) return undefined;
  return JSON.parse(JSON.stringify(value));
}

function rootKey(key, seperator) {
  return String(key).split(seperator).shift();
}

function childPath(key, seperator) {
  return String(key).split(seperator).slice(1).join(seperator);
}

/**
 * Base class for async adapters that store root keys as JSON values.
 * @class
 * @extends EventEmitter
 */
class KeyValueAdapter extends EventEmitter {
  /**
   * Creates a key-value adapter.
   * @param {KeyValueAdapterOptions} [options={}] Adapter options.
   */
  constructor(options = {}) {
    super();
    this.seperator = options.seperator || ".";
    this.message = require("../language/en.json");
    this.ttlKey = "__croxydb_ttl";
  }

  /**
   * Initializes external connections or resources.
   * @returns {Promise<void>}
   */
  async init() {}

  /**
   * Reads a root key from the backing store.
   * @param {string} key Root key.
   * @returns {Promise<*>}
   * @abstract
   */
  async readValue() { throw new TypeError("readValue is not implemented."); }

  /**
   * Writes a root key to the backing store.
   * @param {string} key Root key.
   * @param {*} value Value to write.
   * @returns {Promise<void>}
   * @abstract
   */
  async writeValue() { throw new TypeError("writeValue is not implemented."); }

  /**
   * Deletes a root key from the backing store.
   * @param {string} key Root key.
   * @returns {Promise<void>}
   * @abstract
   */
  async deleteValue() { throw new TypeError("deleteValue is not implemented."); }

  /**
   * Reads all root keys from the backing store.
   * @returns {Promise<Object>}
   * @abstract
   */
  async readAllValues() { throw new TypeError("readAllValues is not implemented."); }

  /**
   * Clears all root keys from the backing store.
   * @returns {Promise<void>}
   * @abstract
   */
  async clearValues() { throw new TypeError("clearValues is not implemented."); }

  /**
   * Reads persisted TTL metadata.
   * @returns {Promise<Object<string, number>>}
   */
  async readTTL() {
    return (await this.readValue(this.ttlKey)) || {};
  }

  /**
   * Writes persisted TTL metadata.
   * @param {Object<string, number>} ttl TTL metadata.
   * @returns {Promise<void>}
   */
  async writeTTL(ttl) {
    await this.writeValue(this.ttlKey, ttl || {});
  }

  /**
   * Sets or removes a TTL entry in a TTL metadata object.
   * @param {Object<string, number>} ttl TTL metadata.
   * @param {string} db Database key.
   * @param {number|Date} [value] TTL value.
   * @returns {void}
   */
  setTTL(ttl, db, value) {
    if (typeof value === "number" && value > 0) {
      ttl[db] = Date.now() + value;
    } else if (value instanceof Date) {
      ttl[db] = value.getTime();
    } else {
      delete ttl[db];
    }
  }

  /**
   * Deletes expired keys before read operations.
   * @returns {Promise<void>}
   */
  async purgeExpired() {
    const ttl = await this.readTTL();
    const now = Date.now();
    let changed = false;

    for (const key of Object.keys(ttl)) {
      if (!ttl[key] || ttl[key] > now) continue;
      await this.delete(key);
      delete ttl[key];
      changed = true;
      this.emit("expire", key);
    }

    if (changed) {
      await this.writeTTL(ttl);
    }
  }

  /**
   * Stores a value.
   * @param {string} db Database key.
   * @param {*} data Value to store.
   * @param {{ttl?: number|Date}} [options={}] Set options.
   * @returns {Promise<*>}
   */
  async set(db, data, options = {}) {
    await this.init();
    if (!db) throw new TypeError(this.message["errors"]["blankName"]);
    if (arguments.length < 2) throw new TypeError(this.message["errors"]["blankData"]);

    const root = rootKey(db, this.seperator);
    const child = childPath(db, this.seperator);
    let value = child ? ((await this.readValue(root)) || {}) : clone(data);
    if (child && (value === null || typeof value !== "object" || Array.isArray(value))) {
      value = {};
    }
    if (child) {
      functions.set(child, clone(data), value, this.seperator);
    }

    await this.writeValue(root, value);

    const ttl = await this.readTTL();
    this.setTTL(ttl, db, options.ttl);
    await this.writeTTL(ttl);

    this.emit("set", db, clone(data));
    return await this.get(db);
  }

  /**
   * Gets a value.
   * @param {string} db Database key.
   * @returns {Promise<*|undefined>}
   */
  async get(db) {
    await this.init();
    if (!db) throw new TypeError(this.message["errors"]["blankName"]);
    await this.purgeExpired();

    const root = rootKey(db, this.seperator);
    const child = childPath(db, this.seperator);
    const value = await this.readValue(root);
    return clone(child ? functions.get(value, this.seperator, ...child.split(this.seperator)) : value);
  }

  /**
   * Alias of {@link KeyValueAdapter#get}.
   * @param {string} db Database key.
   * @returns {Promise<*|undefined>}
   */
  async fetch(db) {
    return await this.get(db);
  }

  /**
   * Checks whether a key exists.
   * @param {string} db Database key.
   * @returns {Promise<boolean>}
   */
  async has(db) {
    await this.init();
    if (!db) throw new TypeError(this.message["errors"]["blankName"]);
    await this.purgeExpired();

    const root = rootKey(db, this.seperator);
    const child = childPath(db, this.seperator);
    if (!child) {
      return (await this.readValue(root)) !== undefined;
    }
    const value = await this.readValue(root);
    return functions.has(value, this.seperator, ...child.split(this.seperator));
  }

  /**
   * Deletes a key.
   * @param {string} db Database key.
   * @returns {Promise<boolean>}
   */
  async delete(db) {
    await this.init();
    if (!db) throw new TypeError(this.message["errors"]["blankName"]);

    const root = rootKey(db, this.seperator);
    const child = childPath(db, this.seperator);
    if (!child) {
      await this.deleteValue(root);
    } else {
      const value = await this.readValue(root);
      if (value === undefined) return false;
      functions.remove(value, child, this.seperator);
      await this.writeValue(root, value);
    }

    const ttl = await this.readTTL();
    delete ttl[db];
    await this.writeTTL(ttl);
    this.emit("delete", db);
    return true;
  }

  /**
   * Adds a number.
   * @param {string} db Database key.
   * @param {number} number Number to add.
   * @returns {Promise<number>}
   */
  async add(db, number) {
    if (!db) throw new TypeError(this.message["errors"]["blankName"]);
    if (number !== 0 && !number) throw new TypeError(this.message["errors"]["blankData"]);
    if (isNaN(number)) throw new TypeError(this.message["errors"]["blankNumber"]);
    const current = await this.get(db);
    await this.set(db, Number(current ? (isNaN(current) ? Number(number) : current + Number(number)) : Number(number)));
    return await this.get(db);
  }

  /**
   * Subtracts a number.
   * @param {string} db Database key.
   * @param {number} number Number to subtract.
   * @returns {Promise<number>}
   */
  async subtract(db, number) {
    if (!db) throw new TypeError(this.message["errors"]["blankName"]);
    if (number !== 0 && !number) throw new TypeError(this.message["errors"]["blankData"]);
    const next = ((await this.get(db)) || 0) - Number(number);
    await this.set(db, next);
    return next;
  }

  /**
   * Pushes a value into an array.
   * @param {string} db Database key.
   * @param {*} data Value to push.
   * @returns {Promise<Array<*>>}
   */
  async push(db, data) {
    if (!db) throw new TypeError(this.message["errors"]["blankName"]);
    if (arguments.length < 2) throw new TypeError(this.message["errors"]["blankData"]);
    const current = await this.get(db);
    const arr = Array.isArray(current) ? current : [];
    arr.push(data);
    await this.set(db, arr);
    return await this.get(db);
  }

  /**
   * Removes matching values from an array.
   * @param {string} db Database key.
   * @param {*} data Value to remove.
   * @returns {Promise<Array<*>>}
   */
  async unpush(db, data) {
    if (!db) throw new TypeError(this.message["errors"]["blankName"]);
    if (arguments.length < 2) throw new TypeError(this.message["errors"]["blankData"]);
    const current = await this.get(db);
    const arr = Array.isArray(current) ? current.filter((x) => x !== data) : [];
    await this.set(db, arr);
    return await this.get(db);
  }

  /**
   * Deletes an array item by one-based priority index.
   * @param {string} db Database key.
   * @param {number} number One-based array index.
   * @returns {Promise<Array<*>|false>}
   */
  async delByPriority(db, number) {
    if (!db) throw new TypeError(this.message["errors"]["blankData"]);
    if (number !== 0 && !number) throw new TypeError(this.message["errors"]["blankNumber"]);
    if (isNaN(number)) throw new TypeError(this.message["errors"]["blankNumber"]);
    const current = await this.get(db);
    if (!Array.isArray(current) || current.length < 1) return false;
    current.splice(number - 1, 1);
    await this.set(db, current);
    return await this.get(db);
  }

  /**
   * Replaces an array item by one-based priority index.
   * @param {string} db Database key.
   * @param {*} data Replacement value.
   * @param {number} number One-based array index.
   * @returns {Promise<Array<*>|false>}
   */
  async setByPriority(db, data, number) {
    if (!db) throw new TypeError(this.message["errors"]["blankData"]);
    if (arguments.length < 2) throw new TypeError(this.message["errors"]["blankData"]);
    if (number !== 0 && !number) throw new TypeError(this.message["errors"]["blankNumber"]);
    if (isNaN(number)) throw new TypeError(this.message["errors"]["blankNumber"]);
    const current = await this.get(db);
    if (!Array.isArray(current) || current.length < 1) return false;
    current[number - 1] = data;
    await this.set(db, current);
    return await this.get(db);
  }

  /**
   * Returns all stored values.
   * @returns {Promise<Object>}
   */
  async all() {
    await this.init();
    await this.purgeExpired();
    const values = await this.readAllValues();
    delete values[this.ttlKey];
    return clone(values);
  }

  /**
   * Deletes all stored values.
   * @returns {Promise<true>}
   */
  async deleteAll() {
    await this.init();
    await this.clearValues();
    await this.writeTTL({});
    this.emit("deleteAll");
    return true;
  }

  async setAsync(db, data, options) { return await this.set(db, data, options); }
  async getAsync(db) { return await this.get(db); }
  async fetchAsync(db) { return await this.fetch(db); }
  async hasAsync(db) { return await this.has(db); }
  async deleteAsync(db) { return await this.delete(db); }
  async addAsync(db, number) { return await this.add(db, number); }
  async subtractAsync(db, number) { return await this.subtract(db, number); }
  async pushAsync(db, data) { return await this.push(db, data); }
  async unpushAsync(db, data) { return await this.unpush(db, data); }
  async allAsync() { return await this.all(); }
  async deleteAllAsync() { return await this.deleteAll(); }
}

module.exports = KeyValueAdapter;
